#[derive(Debug, Clone)]
struct RefreshConfig {
    auto_refresh: bool,
    refresh_interval: u64,
    auto_fetch: bool,
    fetch_interval: u64,
}
impl Default for RefreshConfig {
    fn default() -> Self {
        Self {
            auto_refresh: true,
            refresh_interval: 10,
            auto_fetch: true,
            fetch_interval: 60,
        }
    }
}

fn load_config() -> RefreshConfig {
    let mut cfg = RefreshConfig::default();
    let path = dirs::config_dir().map(|p| p.join("keifu").join("config.toml"));
    if let Some(p) = path {
        if let Ok(content) = std::fs::read_to_string(&p) {
            if let Ok(parsed) = content.parse::<toml::Value>() {
                if let Some(refresh) = parsed.get("refresh") {
                    if let Some(v) = refresh.get("auto_refresh").and_then(|v| v.as_bool()) {
                        cfg.auto_refresh = v;
                    }
                    if let Some(v) = refresh.get("refresh_interval").and_then(|v| v.as_integer()) {
                        let mut iv = v as u64;
                        if iv < 1 { iv = 1; }
                        cfg.refresh_interval = iv;
                    }
                    if let Some(v) = refresh.get("auto_fetch").and_then(|v| v.as_bool()) {
                        cfg.auto_fetch = v;
                    }
                    if let Some(v) = refresh.get("fetch_interval").and_then(|v| v.as_integer()) {
                        let mut iv = v as u64;
                        if iv < 10 { iv = 10; }
                        cfg.fetch_interval = iv;
                    }
                }
            }
        }
    }
    cfg
}

// Git data structures
#[derive(Debug, Clone)]
struct CommitInfo {
    hash: String,
    short: String,
    message_subject: String,
    full_message: String,
    author_name: String,
    author_email: String,
    date_str: String, // YYYY-MM-DD
    datetime_str: String, // YYYY-MM-DD HH:MM:SS
    timestamp: i64,
    parents: Vec<String>, // full hashes
    parent_shorts: Vec<String>,
    branches: Vec<String>, // branch names pointing here (local + remote display names?)
    // for graph
    is_head: bool,
}

#[derive(Debug, Clone)]
struct BranchInfo {
    name: String, // e.g., "master" or "origin/feat"
    is_remote: bool,
    is_head: bool,
    commit: String, // full hash
    upstream: Option<String>,
}

#[derive(Debug, Clone)]
struct FileChange {
    status: char, // M, A, D, R, etc.
    path: String,
    added: i64,
    deleted: i64,
}

#[derive(Debug, Clone)]
struct RepoData {
    commits: Vec<CommitInfo>, // sorted date desc, max 500
    branches: Vec<BranchInfo>,
    head_branch: Option<String>, // None if detached
    head_hash: Option<String>,
    is_detached: bool,
    repo_name: String,
    uncommitted: Option<UncommittedInfo>,
}

#[derive(Debug, Clone)]
struct UncommittedInfo {
    files: Vec<FileChange>,
    total_added: i64,
    total_deleted: i64,
}

fn run_git(args: &[&str]) -> Result<String> {
    let out = ProcCommand::new("git").args(args).output()?;
    if out.status.success() {
        Ok(String::from_utf8_lossy(&out.stdout).to_string())
    } else {
        let err = String::from_utf8_lossy(&out.stderr).to_string();
        anyhow::bail!("{}", err)
    }
}

fn load_repo_data() -> Result<RepoData> {
    // repo name = directory basename
    let toplevel = run_git(&["rev-parse", "--show-toplevel"]).unwrap_or_else(|_| ".".to_string());
    let toplevel = toplevel.trim().to_string();
    let repo_name = std::path::Path::new(&toplevel).file_name().and_then(|s| s.to_str()).unwrap_or("repo").to_string();

    // HEAD info
    let head_branch_out = ProcCommand::new("git").args(&["symbolic-ref", "--short", "HEAD"]).output();
    let (head_branch, is_detached) = match head_branch_out {
        Ok(o) if o.status.success() => {
            let b = String::from_utf8_lossy(&o.stdout).trim().to_string();
            (Some(b), false)
        }
        _ => (None, true),
    };
    let head_hash = ProcCommand::new("git").args(&["rev-parse", "HEAD"]).output().ok().and_then(|o| {
        if o.status.success() { Some(String::from_utf8_lossy(&o.stdout).trim().to_string()) } else { None }
    });

    // branches: git for-each-ref
    let mut branches: Vec<BranchInfo> = Vec::new();
    // local branches
    if let Ok(out) = run_git(&["for-each-ref", "--format=%(refname:short)%00%(objectname)%00%(upstream:short)", "refs/heads/"]) {
        for line in out.lines() {
            if line.is_empty() { continue; }
            let parts: Vec<&str> = line.split('\0').collect();
            let name = parts.get(0).unwrap_or(&"").to_string();
            let commit = parts.get(1).unwrap_or(&"").to_string();
            let upstream = parts.get(2).map(|s| s.to_string()).filter(|s| !s.is_empty());
            let is_head = head_branch.as_ref() == Some(&name);
            branches.push(BranchInfo { name, is_remote: false, is_head, commit, upstream });
        }
    }
    // remote branches
    if let Ok(out) = run_git(&["for-each-ref", "--format=%(refname:short)%00%(objectname)", "refs/remotes/"]) {
        for line in out.lines() {
            if line.is_empty() { continue; }
            // skip origin/HEAD
            if line.starts_with("origin/HEAD") { continue; }
            let parts: Vec<&str> = line.split('\0').collect();
            let name = parts.get(0).unwrap_or(&"").to_string();
            // skip symbolic?
            if name.ends_with("/HEAD") { continue; }
            let commit = parts.get(1).unwrap_or(&"").to_string();
            branches.push(BranchInfo { name, is_remote: true, is_head: false, commit, upstream: None });
        }
    }

    // commits: git log --all --format with date-order? Use --date-order to sort by date? Original seems date desc.
    // We'll use: git log --all --date-order --format=%H%x00%P%x00%an%x00%ae%x00%ct%x00%s%x00%b%x1f  (use \x1f as record sep?)
    // Simpler: use %H|%P|%an|... with careful escaping? Messages may contain |, so use \x00 and \x1f.
    let log_out = ProcCommand::new("git").args(&[
        "log", "--all", "--date-order", "--format=%H%x00%P%x00%an%x00%ae%x00%ct%x00%s%x00%b%x1e", "--date=unix", "--max-count=500"
    ]).output();
    let mut commits: Vec<CommitInfo> = Vec::new();
    if let Ok(o) = log_out {
