                if record.is_empty() { continue; }
                // split by \x00, but subject/body may contain? They shouldn't contain \x00.
                let parts: Vec<&str> = record.split('\x00').collect();
                if parts.len() < 7 { continue; }
                let hash = parts[0].trim().to_string();
