                let parents_str = parts[1].trim();
                let parents: Vec<String> = if parents_str.is_empty() { vec![] } else { parents_str.split_whitespace().map(|s| s.to_string()).collect() };
                let parent_shorts: Vec<String> = parents.iter().map(|p| p[..7.min(p.len())].to_string()).collect();
                let an = parts[2].to_string();
                let ae = parts[3].to_string();
                let ct: i64 = parts[4].trim().parse().unwrap_or(0);
                let subject = parts[5].to_string();
                let body = if parts.len() > 6 { parts[6].to_string() } else { "".to_string() };
                // full message = subject + body?
                let full_message = if body.trim().is_empty() { subject.clone() } else { format!("{}\n{}", subject, body) };
                // date strings in local time? Original shows dates like 2024-01-04 10:00:00 - that's committer date? Use chrono with local?
                // We'll use UTC? Actually GIT_AUTHOR_DATE etc are in local? The test dates are UTC? Let's use chrono Local? Simpler: use chrono DateTime from timestamp in local timezone? Original likely uses local time? But test dates are 10:00:00 regardless of TZ? Our container TZ is UTC, so 10:00:00 UTC will show 10:00:00. Good.
                // Use chrono::Local? Or UTC? Let's use Local to match original (which likely uses local).
