fn load_uncommitted() -> Option<UncommittedInfo> {
    // git status --porcelain | grep -v "^??"  (exclude untracked)
    let status_out = ProcCommand::new("git").args(&["status", "--porcelain"]).output().ok()?;
    if !status_out.status.success() { return None; }
    let status = String::from_utf8_lossy(&status_out.stdout).to_string();
    let mut has_changes = false;
    for line in status.lines() {
        if line.is_empty() { continue; }
        if line.starts_with("??") { continue; }
        has_changes = true;
        break;
    }
    if !has_changes {
        // also check staged? status already includes staged. If no changes, return None.
        return None;
    }
    // get diff HEAD --numstat and --name-status
    let numstat_out = ProcCommand::new("git").args(&["diff", "HEAD", "--numstat"]).output().ok()?;
