#[derive(Debug, Clone)]
struct CommitInfo {
    hash: String,
    short: String,
    message_subject: String,
    full_message: String,
    author_name: String,
    author_email: String,
    date_str: String, // YYYY-MM-DD
    datetime_str: String, // YYYY-MM-DD HH:MM:SS
    timestamp: i64,
    parents: Vec<String>, // full hashes
    parent_shorts: Vec<String>,
    branches: Vec<String>, // branch names pointing here (local + remote display names?)
    // for graph
    is_head: bool,
}

#[derive(Debug, Clone)]
struct BranchInfo {
    name: String, // e.g., "master" or "origin/feat"
    is_remote: bool,
    is_head: bool,
    commit: String, // full hash
    upstream: Option<String>,
}

#[derive(Debug, Clone)]
struct FileChange {
    status: char, // M, A, D, R, etc.
    path: String,
    added: i64,
    deleted: i64,
}

#[derive(Debug, Clone)]
struct RepoData {
    commits: Vec<CommitInfo>, // sorted date desc, max 500
    branches: Vec<BranchInfo>,
    head_branch: Option<String>, // None if detached
    head_hash: Option<String>,
    is_detached: bool,
    repo_name: String,
    uncommitted: Option<UncommittedInfo>,
}

#[derive(Debug, Clone)]
struct UncommittedInfo {
    files: Vec<FileChange>,
    total_added: i64,
    total_deleted: i64,
}

fn run_git(args: &[&str]) -> Result<String> {
    let out = ProcCommand::new("git").args(args).output()?;
    if out.status.success() {
        Ok(String::from_utf8_lossy(&out.stdout).to_string())
    } else {
        let err = String::from_utf8_lossy(&out.stderr).to_string();
        anyhow::bail!("{}", err)
    }
}

