        status_map.insert(path, ch);
    }
    let mut files: Vec<FileChange> = Vec::new();
    let mut total_a = 0;
    let mut total_d = 0;
    for line in numstat.lines() {
        if line.is_empty() { continue; }
        // binary files show "-\t-\tfile" -> skip per docs (binary excluded)
        let parts: Vec<&str> = line.split('\t').collect();
        if parts.len() < 3 { continue; }
        let a_str = parts[0];
        let d_str = parts[1];
        let path = parts[2].to_string();
        if a_str == "-" || d_str == "-" {
            continue; // binary
        }
        let a: i64 = a_str.parse().unwrap_or(0);
        let d: i64 = d_str.parse().unwrap_or(0);
        total_a += a;
        total_d += d;
        let st = *status_map.get(&path).unwrap_or(&'M');
