#[derive(Debug, Clone)]
struct RefreshConfig {
    auto_refresh: bool,
    refresh_interval: u64,
    auto_fetch: bool,
    fetch_interval: u64,
}
impl Default for RefreshConfig {
    fn default() -> Self {
        Self {
            auto_refresh: true,
            refresh_interval: 10,
            auto_fetch: true,
            fetch_interval: 60,
        }
    }
}

fn load_config() -> RefreshConfig {
    let mut cfg = RefreshConfig::default();
    let path = dirs::config_dir().map(|p| p.join("keifu").join("config.toml"));
    if let Some(p) = path {
        if let Ok(content) = std::fs::read_to_string(&p) {
            if let Ok(parsed) = content.parse::<toml::Value>() {
                if let Some(refresh) = parsed.get("refresh") {
                    if let Some(v) = refresh.get("auto_refresh").and_then(|v| v.as_bool()) {
                        cfg.auto_refresh = v;
                    }
                    if let Some(v) = refresh.get("refresh_interval").and_then(|v| v.as_integer()) {
                        let mut iv = v as u64;
                        if iv < 1 { iv = 1; }
                        cfg.refresh_interval = iv;
                    }
                    if let Some(v) = refresh.get("auto_fetch").and_then(|v| v.as_bool()) {
                        cfg.auto_fetch = v;
                    }
                    if let Some(v) = refresh.get("fetch_interval").and_then(|v| v.as_integer()) {
                        let mut iv = v as u64;
                        if iv < 10 { iv = 10; }
                        cfg.fetch_interval = iv;
                    }
                }
            }
        }
    }
    cfg
}

