#[derive(Debug, Clone)]
struct CommitInfo {
    hash: String,
    short: String,
    message_subject: String,
    full_message: String,
    author_name: String,
    author_email: String,
    date_str: String, // YYYY-MM-DD
    datetime_str: String, // YYYY-MM-DD HH:MM:SS
