#[derive(Debug, Clone, PartialEq)]
enum AppMode {
    Normal,
    Help,
    Search,
    NewBranch,
    Confirm,
    Error,
}

struct App {
    data: RepoData,
    display_rows: Vec<(DisplayRow, String)>, // (row, graph)
    // selection: index into display_rows that is Commit/Uncommitted? Or commit list index?
    // We'll store selected_display: index into display_rows where row is Commit/Uncommitted
    selected: usize, // index into filtered selectable rows? Simpler: index into display_rows, but skip Graph rows when navigating
    // For uncommitted, display_rows includes Uncommitted at top if present? We'll include.
    branch_sel: HashMap<String, usize>, // commit hash -> selected branch idx (for commits with multiple branches), plus "uncommitted" not needed
    mode: AppMode,
    search_query: String,
    search_results: Vec<(String, usize)>, // (branch name, commit idx)
    search_sel: usize,
    new_branch_input: String,
    confirm_branch: Option<String>,
    error_msg: Option<String>,
    info_msg: Option<String>,
    // for status error that requires Esc/Enter to dismiss
    show_branches_dropdown: bool, // actually dropdown shows when selected commit has >1 branch? Original shows automatically. We'll show when selected commit has >1 branch and mode==Normal.
    scroll_offset: usize,
    config: RefreshConfig,
    last_refresh: Instant,
    last_fetch: Instant,
    fetching: bool,
    fetch_msg: Option<String>,
}

impl App {
    fn new(data: RepoData, config: RefreshConfig) -> Self {
        let mut app = Self {
            display_rows: vec![],
            selected: 0,
            branch_sel: HashMap::new(),
            mode: AppMode::Normal,
            search_query: String::new(),
            search_results: vec![],
            search_sel: 0,
            new_branch_input: String::new(),
            confirm_branch: None,
            error_msg: None,
            info_msg: None,
            show_branches_dropdown: false,
            scroll_offset: 0,
            config,
            last_refresh: Instant::now(),
            last_fetch: Instant::now(),
            fetching: false,
            fetch_msg: None,
            data,
        };
        app.rebuild_rows();
        // Select HEAD? Original selects top (newest) initially, not HEAD. Let's select top (0).
        app.selected = 0;
        app
    }

    fn rebuild_rows(&mut self) {
        // Build commits list including uncommitted?
        // display_rows: if uncommitted present, first row is Uncommitted with graph "●"? Actually uncommitted graph? Observed: "●  uncommitted changes (1)" with graph "●"? Let's see: uncommitted row graph "●" (no lanes?).
        // For simplicity, uncommitted graph is "●" (or "◉" if HEAD? No, HEAD is still on branch commit, uncommitted is separate, not HEAD? Actually uncommitted row shows "●" not "◉"? In capture, uncommitted row was "●  uncommitted changes (1)" with "●", while HEAD commit (master) was "◉". So uncommitted is "●".
        let mut rows: Vec<(DisplayRow, String)> = Vec::new();
        if self.data.uncommitted.is_some() {
            rows.push((DisplayRow::Uncommitted, "●".to_string()));
        }
        let graphs = build_graph(&self.data.commits);
        // graphs length == commits.len(), but rows need to interleave Graph rows from build_display_rows?
        // Our build_graph currently returns one per commit, but build_display_rows returns with extras. Let's use build_display_rows instead.
        let disp = build_display_rows(&self.data.commits);
        for (row, g) in disp {
            rows.push((row, g));
        }
        self.display_rows = rows;
        // Clamp selected
        let selectable: Vec<usize> = self.selectable_indices();
        if selectable.is_empty() {
            self.selected = 0;
        } else if !selectable.contains(&self.selected) {
            // keep selected if possible, else top
            if self.selected >= self.display_rows.len() {
                self.selected = *selectable.first().unwrap();
            } else {
                // if selected points to Graph row, move to nearest selectable?
                // Find next selectable >= selected, or first
                let mut found = None;
                for &idx in &selectable {
                    if idx >= self.selected {
                        found = Some(idx);
                        break;
                    }
                }
                self.selected = found.unwrap_or(selectable[0]);
            }
        }
    }

    fn selectable_indices(&self) -> Vec<usize> {
        self.display_rows.iter().enumerate().filter_map(|(i, (r, _))| match r {
            DisplayRow::Commit(_) | DisplayRow::Uncommitted => Some(i),
            DisplayRow::Graph(_) => None,
        }).collect()
    }

    fn selected_row(&self) -> Option<&(DisplayRow, String)> {
        self.display_rows.get(self.selected)
    }

    fn selected_commit(&self) -> Option<&CommitInfo> {
        match self.display_rows.get(self.selected) {
            Some((DisplayRow::Commit(idx), _)) => self.data.commits.get(*idx),
            _ => None,
        }
    }

    fn selected_commit_idx(&self) -> Option<usize> {
        match self.display_rows.get(self.selected) {
            Some((DisplayRow::Commit(idx), _)) => Some(*idx),
            _ => None,
        }
    }

    fn is_uncommitted_selected(&self) -> bool {
        matches!(self.display_rows.get(self.selected), Some((DisplayRow::Uncommitted, _)))
    }

    fn move_down(&mut self) {
        let sel = self.selectable_indices();
        if sel.is_empty() { return; }
        if let Some(pos) = sel.iter().position(|&x| x == self.selected) {
            if pos + 1 < sel.len() {
                self.selected = sel[pos+1];
            }
        } else {
            self.selected = sel[0];
        }
    }
    fn move_up(&mut self) {
        let sel = self.selectable_indices();
        if sel.is_empty() { return; }
        if let Some(pos) = sel.iter().position(|&x| x == self.selected) {
            if pos > 0 {
                self.selected = sel[pos-1];
            }
        } else {
            self.selected = sel[0];
        }
    }
    fn goto_top(&mut self) {
        if let Some(&first) = self.selectable_indices().first() {
            self.selected = first;
        }
    }
    fn goto_bottom(&mut self) {
        if let Some(&last) = self.selectable_indices().last() {
            self.selected = last;
        }
    }
    fn page_down(&mut self, page: usize) {
        let sel = self.selectable_indices();
        if sel.is_empty() { return; }
        if let Some(pos) = sel.iter().position(|&x| x == self.selected) {
            let np = (pos + page).min(sel.len()-1);
            self.selected = sel[np];
        }
    }
    fn page_up(&mut self, page: usize) {
        let sel = self.selectable_indices();
        if sel.is_empty() { return; }
        if let Some(pos) = sel.iter().position(|&x| x == self.selected) {
            let np = pos.saturating_sub(page);
            self.selected = sel[np];
        }
    }
    fn jump_to_head(&mut self) {
        // Find commit with is_head, or if uncommitted? HEAD is branch commit, not uncommitted. Jump to HEAD commit.
        for (i, (row, _)) in self.display_rows.iter().enumerate() {
            match row {
                DisplayRow::Commit(idx) => {
                    if self.data.commits[*idx].is_head {
                        self.selected = i;
                        return;
                    }
                }
                _ => {}
            }
        }
        // If HEAD detached and no is_head? Then head_hash? Find commit with hash == head_hash
        if let Some(hh) = &self.data.head_hash {
            for (i, (row, _)) in self.display_rows.iter().enumerate() {
                if let DisplayRow::Commit(idx) = row {
                    if self.data.commits[*idx].hash == *hh {
                        self.selected = i;
                        return;
                    }
                }
            }
        }
    }
    fn jump_to_next_branch(&mut self) {
        // Find next selectable with branches
        let sel = self.selectable_indices();
        if sel.is_empty() { return; }
        let cur_pos = sel.iter().position(|&x| x == self.selected).unwrap_or(0);
        for offset in 1..=sel.len() {
            let np = (cur_pos + offset) % sel.len();
            let idx = sel[np];
            let has_branch = match &self.display_rows[idx].0 {
                DisplayRow::Commit(cidx) => !self.data.commits[*cidx].branches.is_empty(),
                DisplayRow::Uncommitted => false,
                _ => false,
            };
            if has_branch {
                self.selected = idx;
                return;
            }
        }
    }
    fn jump_to_prev_branch(&mut self) {
        let sel = self.selectable_indices();
        if sel.is_empty() { return; }
        let cur_pos = sel.iter().position(|&x| x == self.selected).unwrap_or(0);
        for offset in 1..=sel.len() {
            let np = (cur_pos + sel.len() - offset % sel.len()) % sel.len();
            let idx = sel[np];
            let has_branch = match &self.display_rows[idx].0 {
                DisplayRow::Commit(cidx) => !self.data.commits[*cidx].branches.is_empty(),
                DisplayRow::Uncommitted => false,
                _ => false,
            };
            if has_branch {
                self.selected = idx;
                return;
            }
        }
    }

    fn current_branch_name(&self) -> Option<String> {
        // Selected branch for current commit (considering branch_sel)
        if self.is_uncommitted_selected() {
            return None;
        }
        if let Some(c) = self.selected_commit() {
            if c.branches.is_empty() {
                return None;
            }
            let sel_idx = *self.branch_sel.get(&c.hash).unwrap_or(&0);
            let idx = sel_idx.min(c.branches.len()-1);
