            }
            KeyCode::Char('j') | KeyCode::Char('J') => {
                if !app.search_results.is_empty() && app.search_sel + 1 < app.search_results.len() {
                    app.search_sel += 1;
                }
                return Ok(false);
            }
            _ => {}
        }
    }
    match key.code {
        KeyCode::Esc => {
            app.mode = AppMode::Normal;
            app.search_query.clear();
            app.search_results.clear();
            Ok(false)
        }
        KeyCode::Enter => {
            if !app.search_results.is_empty() {
                let (_, cidx) = app.search_results[app.search_sel].clone();
                // Find display index for this commit
                for (i, (row, _)) in app.display_rows.iter().enumerate() {
