            Ok(false)
        }
        KeyCode::Char(c) => {
            // Typing (ignore control?)
            if !key.modifiers.contains(KeyModifiers::CONTROL) && !key.modifiers.contains(KeyModifiers::ALT) {
                app.search_query.push(c);
                app.update_search_results();
            }
            Ok(false)
        }
        _ => Ok(false),
    }
