fn run_tui(config: RefreshConfig) -> Result<()> {
    enable_raw_mode()?;
    let mut stdout = std::io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let data = load_repo_data().context("Failed to load repository")?;
    let mut app = App::new(data, config.clone());

    let mut last_refresh = Instant::now();
    let mut last_fetch = Instant::now();

    loop {
        terminal.draw(|f| draw_ui(f, &mut app))?;

        // Check auto-refresh/fetch timers
        let now = Instant::now();
        if app.config.auto_refresh && now.duration_since(last_refresh).as_secs() >= app.config.refresh_interval {
            app.refresh();
            last_refresh = now;
        }
        if app.config.auto_fetch && now.duration_since(last_fetch).as_secs() >= app.config.fetch_interval {
            // auto-fetch: run git fetch origin without blocking? For simplicity, run synchronously and ignore errors (no status display for auto-fetch? Original probably shows fetching? But to avoid disrupting UI, just fetch silently and refresh)
            let _ = ProcCommand::new("git").args(&["fetch", "origin"]).output();
            app.refresh();
            last_fetch = now;
        }

        // Poll events with timeout 200ms to allow timers
        if event::poll(Duration::from_millis(200))? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Press {
                    continue;
                }
                let quit = handle_key(&mut app, key, &mut terminal)?;
                if quit {
                    break;
                }
                // Reset refresh timer on manual actions? Not needed
            } else if let Event::Resize(_, _) = event::read()? {
                // just redraw
            }
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}

fn handle_key(app: &mut App, key: event::KeyEvent, terminal: &mut Terminal<ratatui::backend::CrosstermBackend<Stdout>>) -> Result<bool> {
    // Returns true if should quit
    match app.mode {
        AppMode::Normal => handle_normal_key(app, key),
        AppMode::Help => {
            match key.code {
                KeyCode::Char('?') | KeyCode::Esc | KeyCode::Char('q') => {
