                                }
                            }
                            break;
                        }
                    }
                }
            }
            app.mode = AppMode::Normal;
            app.search_query.clear();
            app.search_results.clear();
            Ok(false)
        }
        KeyCode::Up => {
            if !app.search_results.is_empty() && app.search_sel > 0 {
                app.search_sel -= 1;
            }
            Ok(false)
        }
        KeyCode::Down => {
            if !app.search_results.is_empty() && app.search_sel + 1 < app.search_results.len() {
                app.search_sel += 1;
            }
            Ok(false)
        }
        KeyCode::Backspace => {
            if app.search_query.is_empty() {
                // Cancel as per docs: empty + Backspace cancels
