fn draw_ui(f: &mut Frame, app: &mut App) {
    let area = f.area();
    if area.width < 10 || area.height < 5 {
        return;
    }
    // Layout: vertical: Commits (70%), Detail (30%), Status (1)
    let total_h = area.height as usize;
    let status_h = 1;
    let main_h = total_h.saturating_sub(status_h);
    let commits_h = main_h * 70 / 100;
    let detail_h = main_h.saturating_sub(commits_h);
    let commits_area = Rect { x: area.x, y: area.y, width: area.width, height: commits_h as u16 };
    let detail_area = Rect { x: area.x, y: area.y + commits_h as u16, width: area.width, height: detail_h as u16 };
    let status_area = Rect { x: area.x, y: area.y + (commits_h + detail_h) as u16, width: area.width, height: 1 };

    draw_commits(f, app, commits_area);
    draw_detail(f, app, detail_area);
    draw_status(f, app, status_area);

    // Popups
    match app.mode {
        AppMode::Help => draw_help(f, app, area),
        AppMode::Search => draw_search(f, app, area),
        AppMode::NewBranch => draw_new_branch(f, app, area),
        AppMode::Confirm => draw_confirm(f, app, area),
        AppMode::Error => {
            // Error is shown in status, not popup, except for create/delete? Actually create error is status, not popup. So no popup.
            // But need to ensure status shows error. That's already in draw_status.
        }
        AppMode::Normal => {
            // Branches dropdown if selected commit has multiple branches
            if let Some(c) = app.selected_commit() {
                if c.branches.len() > 1 {
                    draw_branches_dropdown(f, app, commits_area);
                }
            }
        }
    }
}

