    vec![]
}

fn build_file_lines(files: &[FileChange], total_a: i64, total_d: i64) -> Vec<Line> {
    let mut lines: Vec<Line> = Vec::new();
    // Header: "N files changed  +A -D" (with 2 spaces between changed and +? Actually observed "3 files changed  +2 -1" with 2 spaces)
    let header = format!("{} files changed  +{} -{}", files.len(), total_a, total_d);
    // Style: "N files changed" bold, "+A" green, "-D" red
    lines.push(Line::from(vec![
        Span::styled(format!("{} files changed", files.len()), Style::default().add_modifier(Modifier::BOLD)),
        Span::raw("  "),
        Span::styled(format!("+{}", total_a), Style::default().fg(Color::Indexed(2))),
        Span::raw(" "),
        Span::styled(format!("-{}", total_d), Style::default().fg(Color::Indexed(1))),
    ]));
    lines.push(Line::from(""));
    for f in files {
        let status_str = format!(" {} ", f.status);
        let status_color = match f.status {
            'A' => Color::Indexed(2),
            'D' => Color::Indexed(1),
            'M' => Color::Indexed(3),
            'R' => Color::Indexed(5),
            _ => Color::Indexed(3),
        };
        lines.push(Line::from(vec![
            Span::styled(status_str, Style::default().fg(status_color)),
            Span::raw(format!("{} ", f.path)),
            Span::styled(format!("+{}", f.added), Style::default().fg(Color::Indexed(2))),
            Span::raw(" "),
            Span::styled(format!("-{}", f.deleted), Style::default().fg(Color::Indexed(1))),
        ]));
